#!/bin/sh
# Emoji width and font coverage tables for react-hterm in Blink.
# Every cell is padded assuming the "correct" width, so a | border that does
# not line up means the terminal allotted, or drew, a different width.
# Table 1 widths were recorded with jsdom over the Blink bundle at 7c69415, alone
# ("ours") and with the grapheme override from mitchmalone/fix/emoji-row-fit
# 7fee00d7 layered on top ("+mitch").
# Table 2 coverage is from the fonts' character maps; "--" means the font has
# no glyph and WebKit falls through to the next font in the stack.

R='\033[0m'
BG='\033[41m'   # red background = the cells the terminal allotted

echo ''
echo '=== 1. width: ours vs +mitch (7fee00d7) vs correct ==='
printf '| case            | sample   | ours | +mitch | correct |\n'
printf '|-----------------|----------|------|--------|---------|\n'
printf '| heart+VS16      | \xe2\x9d\xa4\xef\xb8\x8f       | 2    | 1!     | 2       |\n'
printf '| keycap 1        | 1\xef\xb8\x8f\xe2\x83\xa3       | 2    | 1!     | 2       |\n'
printf '| a heart+VS16 b  | a\xe2\x9d\xa4\xef\xb8\x8fb     | 4    | 3!     | 4       |\n'
printf '| heart+VS16 cook | \xe2\x9d\xa4\xef\xb8\x8f \xf0\x9f\xa7\x91\xe2\x80\x8d\xf0\x9f\x8d\xb3    | 7!   | 4!     | 5       |\n'
printf '| cook ZWJ        | \xf0\x9f\xa7\x91\xe2\x80\x8d\xf0\x9f\x8d\xb3       | 4!   | 2      | 2       |\n'
printf '| family ZWJ      | \xf0\x9f\x91\xa8\xe2\x80\x8d\xf0\x9f\x91\xa9\xe2\x80\x8d\xf0\x9f\x91\xa7       | 6!   | 2      | 2       |\n'
printf '| thumbs+skin     | \xf0\x9f\x91\x8d\xf0\x9f\x8f\xbb       | 4!   | 2      | 2       |\n'
printf '| rainbow flag    | \xf0\x9f\x8f\xb3\xef\xb8\x8f\xe2\x80\x8d\xf0\x9f\x8c\x88       | 4!   | 2      | 2       |\n'
printf '| ab cook cd      | ab\xf0\x9f\xa7\x91\xe2\x80\x8d\xf0\x9f\x8d\xb3cd   | 8!   | 6      | 6       |\n'
printf '| flag ES         | \xf0\x9f\x87\xaa\xf0\x9f\x87\xb8       | 2    | 2      | 2       |\n'
printf '| scotland        | \xf0\x9f\x8f\xb4\xf3\xa0\x81\xa7\xf3\xa0\x81\xa2\xf3\xa0\x81\xb3\xf3\xa0\x81\xa3\xf3\xa0\x81\xb4\xf3\xa0\x81\xbf       | 2    | 2      | 2       |\n'
printf '| grinning        | \xf0\x9f\x98\x80       | 2    | 2      | 2       |\n'
printf '| bare U+23FA     | \xe2\x8f\xba        | 1    | 1      | 1       |\n'
printf '| U+23FA+VS15     | \xe2\x8f\xba\xef\xb8\x8e        | 1    | 1      | 1       |\n'
printf '| e+acute         | e\xcc\x81x       | 2    | 2      | 2       |\n'
printf '| CJK control     | \xe3\x81\x82\xe3\x81\x84     | 4    | 4      | 4       |\n'
echo '(! = disagrees with correct; on those rows the right border shifts by the difference)'
echo ''
