echo '(bare and +VS15 are 1 column, +VS16 is 2. A glyph that only Apple Color Emoji'
echo ' has draws ~2 cells wide in a 1-cell slot and pushes the rest of its span right.)'
echo ''
echo '=== 3. allotted cells vs glyph: red = what the terminal reserved ==='
printf 'X'; printf "$BG"; printf '\xf0\x9f\x96\xa5'; printf "$R"; printf 'X  U+1F5A5 bare, 1 cell\n'
printf 'X'; printf "$BG"; printf '\xf0\x9f\x96\xa5\xef\xb8\x8e'; printf "$R"; printf 'X  U+1F5A5+VS15, 1 cell\n'
printf 'X'; printf "$BG"; printf '\xf0\x9f\x96\xa5\xef\xb8\x8f'; printf "$R"; printf 'X  U+1F5A5+VS16, 2 cells\n'
printf 'X'; printf "$BG"; printf '\xe2\x8f\xba'; printf "$R"; printf 'X  U+23FA bare, 1 cell\n'
printf 'X'; printf "$BG"; printf '\xe3\x81\x82'; printf "$R"; printf 'X  CJK control, 2 cells\n'
printf 'X'; printf "$BG"; printf '\xf0\x9f\x96\xa5abc'; printf "$R"; printf 'X  U+1F5A5 + abc in one span, 4 cells\n'
echo '(if the X after the red box is pushed right, or abc is clipped, the glyph is'
echo ' wider than its slot: a rendering issue, not a width issue)'
echo ''
